<script setup>
import {saveRecord} from '../api/client'
import AdminContextPanel from '../components/AdminContextPanel.vue'
import AdminCategoryBrowser from '../components/AdminCategoryBrowser.vue'
import {equipmentArt} from '../data/equipmentPresentation'
import AdminSupplyBrief from '../components/AdminSupplyBrief.vue'
import PersonAvatar from '../components/ui/PersonAvatar.vue'
import {workModeLabel} from '../data/masterWorkModes'
import WorkspaceHero from '../components/WorkspaceHero.vue'
import AdminRecordEditor from '../components/AdminRecordEditor.vue'
import AdminRequestModal from '../components/AdminRequestModal.vue'
import DeviceArt from '../components/illustrations/DeviceArt.vue'
import PartArt from '../components/illustrations/PartArt.vue'
import { adminMedia } from '../data/adminMedia'
import {adminPartKind,logAdmin,makePurchaseDrafts} from '../data/adminOperations'
import { computed, reactive, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import Card from '../components/ui/Card.vue'
import Button from '../components/ui/Button.vue'
import Badge from '../components/ui/Badge.vue'
import Input from '../components/ui/Input.vue'
import Select from '../components/ui/Select.vue'
import Modal from '../components/ui/Modal.vue'
import SvgIcon from '../components/ui/SvgIcon.vue'
import PageState from '../components/ui/PageState.vue'
import { useMockPage } from '../composables/useMockPage'
import { toast } from '../composables/useToast'
import { adminRequests, adminClients, adminMasters, adminServices, adminSkills, adminStock, requestView, stockView, masterLoad, statusLabels, statusTones, money, shortDate } from '../data/admin'
const route = useRoute()
const entity = computed(() => route.meta.entity)
const { loading, error, empty, retry } = useMockPage()
const search = ref(''), status = ref(''), channel = ref(''), onlyAttention = ref(false), onlyCritical = ref(false), page = ref(1)
const recordOpen=ref(false),recordEditing=ref(null),newRequestOpen=ref(false),equipment=ref('')
function editRecord(r=null){recordEditing.value=r;recordOpen.value=true}
async function generateOrders(){const n=await makePurchaseDrafts();toast(n?'Черновики закупок обновлены':'Закупка не требуется')}
function deviceIcon(s){return equipmentArt(s?.equipment_category)}
const detail = ref(null), editOpen = ref(false), deleting = ref(null)
const form = reactive({ id: null, name: '', equipment_category: 'Смартфоны', base_price: 0, average_duration_minutes: 60, required_skill_level: 1, is_active: 1 })
const formError = ref('')
const meta = computed(() => ({ requests: { title: 'Все заявки', subtitle: 'Обращения клиентов — от первого контакта до завершения ремонта', icon: 'clipboard' }, clients: { title: 'Клиенты', subtitle: 'Контакты и история обращений в сервис', icon: 'users' }, masters: { title: 'Мастера', subtitle: 'Навыки, специализация и текущая загрузка команды', icon: 'wrench' }, services: { title: 'Услуги', subtitle: 'Каталог работ, стоимость и требования к квалификации', icon: 'store' }, warehouse: { title: 'Склад', subtitle: 'Центральный склад: остатки, резерв и доступное количество', icon: 'box' } })[entity.value])
const source = computed(() => ({ requests: adminRequests.map(requestView), clients: adminClients, masters: adminMasters, services: adminServices, warehouse: adminStock.map(stockView).map(s=>({...s,...adminPartKind(s.part_id)})).sort((a,b)=>a.category.localeCompare(b.category,'ru')||a.name.localeCompare(b.name,'ru')) })[entity.value] ?? [])
const filtered = computed(() => source.value.filter(r => {
 const query = search.value.trim().toLocaleLowerCase('ru-RU')
 const text = entity.value === 'requests' ? `${r.request_number} ${r.client.full_name} ${r.client.phone} ${r.contact_phone??''} ${r.service?.name}` : entity.value === 'warehouse' ? `${r.name} ${r.sku}` : `${r.full_name ?? r.name} ${r.email ?? ''} ${r.phone ?? ''} ${r.equipment_category ?? ''}`
 return (!query || text.toLocaleLowerCase('ru-RU').includes(query)) && (entity.value !== 'requests' || ((!status.value || r.status === status.value) && (!channel.value || r.service_mode === channel.value) && (!onlyAttention.value || r.status === 'new' || r.needs_manual_review))) && (entity.value!=='services'||!equipment.value||r.equipment_category===equipment.value) && (entity.value !== 'warehouse' || ((!onlyCritical.value || r.is_active && r.available < r.min_stock)&&(!equipment.value||r.category===equipment.value)))
}))
const visible = computed(() => filtered.value.slice((page.value - 1) * 10, page.value * 10))
const pages = computed(() => Math.max(1, Math.ceil(filtered.value.length / 10)))
const statusOptions = [{ value: '', label: 'Все статусы' }, ...Object.entries(statusLabels).map(([value, label]) => ({ value, label }))]
const channels = [{ value: '', label: 'Все каналы' }, { value: 'onsite', label: 'Выезд мастера' }, { value: 'dropoff', label: 'В сервисе' }]
const categories = [...new Set(adminServices.map(s => s.equipment_category))]
const hasFilters = computed(() => search.value || status.value || channel.value || onlyAttention.value || onlyCritical.value || equipment.value)
function reset() { search.value = ''; status.value = ''; channel.value = ''; onlyAttention.value = false; onlyCritical.value = false; equipment.value='' }
watch(() => [route.path, route.query.request, route.query.attention, route.query.critical, route.query.status], () => { reset(); page.value = 1; detail.value = null; editOpen.value = false;recordOpen.value=false;newRequestOpen.value=false; status.value = Object.hasOwn(statusLabels, route.query.status) ? route.query.status : ''; onlyAttention.value = route.query.attention === '1'; onlyCritical.value = route.query.critical === '1'; if (entity.value === 'requests' && route.query.request) detail.value = source.value.find(r => r.id === Number(route.query.request)) ?? null }, { immediate: true })
watch([search, status, channel, onlyAttention, onlyCritical,equipment], () => { page.value = 1 })
watch(pages, count => { page.value = Math.min(page.value, count) })
function clientCount(id) { return adminRequests.filter(r => r.user_id === id).length }
function skills(id) { return adminSkills.filter(s => s.master_id === id).map(s => adminServices.find(v => v.id === s.service_id)?.name).filter(Boolean) }
function edit(service) { Object.assign(form, service ?? { id: null, name: '', equipment_category: categories[0], base_price: 0, average_duration_minutes: 60, required_skill_level: 1, is_active: 1 }); formError.value = ''; editOpen.value = true }
async function save() {
 if (form.name.trim().length < 3) { formError.value = 'Введите название услуги: не менее 3 символов.'; return }
 if (!Number.isFinite(Number(form.base_price)) || Number(form.base_price) < 0 || !Number.isInteger(Number(form.average_duration_minutes)) || Number(form.average_duration_minutes) <= 0 || !Number.isInteger(Number(form.required_skill_level)) || Number(form.required_skill_level) < 1) { formError.value = 'Проверьте стоимость, длительность и уровень навыка.'; return }
 const data = { ...form, name: form.name.trim(), base_price: Number(form.base_price), average_duration_minutes: Number(form.average_duration_minutes), required_skill_level: Number(form.required_skill_level), is_active: Number(form.is_active) }
 try{const {id,base_price,...fields}=data;await saveRecord('services',form.id,{...fields,base_price_cents:Math.round(base_price*100)});editOpen.value=false;toast('Услуга сохранена')}catch(e){formError.value=e.message}

}
async function remove(){await saveRecord('services',deleting.value.id,{is_active:0});deleting.value=null;toast('Услуга перенесена в архив')}

</script>
<template>
 <div class="grid gap-6">
  <WorkspaceHero :title="meta.title" :description="meta.subtitle" eyebrow="УПРАВЛЕНИЕ СЕРВИСОМ" :image="adminMedia[entity==='masters'?'team':entity]"><Button v-if="entity==='services'" variant="primary" @click="edit()">Добавить услугу</Button><Button v-else-if="entity==='requests'" variant="primary" @click="newRequestOpen=true">Оформить заявку</Button><template v-else><Button variant="primary" @click="editRecord()">{{entity==='clients'?'Добавить клиента':entity==='masters'?'Добавить мастера':'Добавить запчасть'}}</Button><Button v-if="entity==='warehouse'" to="/admin/orders" variant="outline">Заказы поставщикам</Button></template></WorkspaceHero>
  <PageState :loading="loading" :error="error" :empty="empty" :icon="meta.icon" @retry="retry" :title="`${meta.title}: пока нет записей`">
   <section class="admin-directory-summary"><div><span>{{entity==='warehouse'?'Всего единиц':'Всего записей'}}</span><strong>{{entity==='warehouse'?source.reduce((sum,r)=>sum+r.quantity,0):source.length}}</strong><small>{{entity==='requests'?'История обращений сервиса':'В текущем справочнике'}}</small></div><div><span>{{entity==='requests'?'Требуют внимания':entity==='warehouse'?'В резерве':'Активны'}}</span><strong>{{entity==='requests'?source.filter(r=>r.status==='new'||r.needs_manual_review).length:entity==='warehouse'?source.reduce((sum,r)=>sum+r.reserved_quantity,0):source.filter(r=>(r.is_active??r.is_available)===1).length}}</strong><small>{{entity==='requests'?'Новые и ручная проверка':entity==='warehouse'?'Детали под заявки':'Доступны для работы'}}</small></div><div><span>{{entity==='warehouse'?'Доступно':entity==='masters'?'Назначено на сегодня':entity==='services'?'Категорий техники':entity==='clients'?'С обращениями':'В работе'}}</span><strong>{{entity==='warehouse'?source.reduce((sum,r)=>sum+r.available,0):entity==='masters'?source.reduce((sum,r)=>sum+masterLoad(r),0):entity==='services'?categories.length:entity==='clients'?source.filter(c=>clientCount(c.id)>0).length:adminRequests.filter(r=>['assigned','in_progress','waiting_parts','ready_for_pickup'].includes(r.status)).length}}</strong><small>{{entity==='warehouse'?'Остаток за вычетом резерва':'По текущим данным сервиса'}}</small></div></section>
   <AdminContextPanel v-if="['clients','masters','requests'].includes(entity)" :entity="entity" :selected="status" @filter="v=>{status=v;onlyAttention=false}" @client="v=>search=v"/>
   <AdminSupplyBrief v-if="entity==='warehouse'"/>
   <AdminCategoryBrowser v-if="entity==='services'" :services="adminServices" v-model="equipment"/>
   <Card padding="md"><div class="grid gap-3" :class="entity === 'requests' ? 'lg:grid-cols-[minmax(0,1.6fr)_1fr_1fr]' : entity==='warehouse'?'md:grid-cols-[minmax(0,1.6fr)_1fr]':''"><Input v-model="search" type="search" icon-left="search" :label="entity === 'requests' ? 'Поиск по номеру, клиенту или услуге' : entity === 'warehouse' ? 'Поиск по названию или артикулу' : 'Поиск по справочнику'" placeholder="Начните вводить…"/><Select v-if="entity === 'requests'" v-model="status" label="Статус" :options="statusOptions"/><Select v-if="entity === 'requests'" v-model="channel" label="Канал" :options="channels"/><Select v-if="entity==='warehouse'" v-model="equipment" label="Вид техники" :options="[{value:'',label:'Вся техника'},...[...new Set(source.map(r=>r.category))].map(c=>({value:c,label:c}))]"/></div><div class="mt-4 flex flex-wrap items-center justify-between gap-3"><span class="text-xs text-muted">Найдено <strong class="text-content">{{ filtered.length }}</strong> из {{ source.length }}</span><div class="flex flex-wrap gap-2"><Button v-if="entity === 'requests'" size="sm" :variant="onlyAttention ? 'danger' : 'outline'" :aria-pressed="onlyAttention" @click="onlyAttention = !onlyAttention"><SvgIcon name="alertTriangle" :size="14"/>Требуют внимания</Button><Button v-if="entity === 'warehouse'" size="sm" :variant="onlyCritical ? 'danger' : 'outline'" :aria-pressed="onlyCritical" @click="onlyCritical = !onlyCritical">Критичные остатки</Button><Button v-if="hasFilters" variant="ghost" size="sm" @click="reset">Сбросить фильтры</Button></div></div></Card>
   <PageState :empty="!filtered.length" title="Ничего не найдено" description="Попробуйте другое название или сбросьте фильтры." icon="search"><template #action><Button v-if="hasFilters" variant="outline" @click="reset">Сбросить фильтры</Button></template>
    <Card padding="none" class="overflow-hidden"><div class="overflow-x-auto"><table class="directory-table w-full text-left text-sm" :aria-label="meta.title"><thead class="bg-surface2/70 text-[10px] uppercase tracking-wider text-muted"><tr v-if="entity === 'requests'"><th>Заявка / клиент</th><th>Услуга</th><th>Канал</th><th>Статус</th><th>Мастер</th><th>Создана</th></tr><tr v-else-if="entity === 'clients'"><th>Клиент</th><th>Email</th><th>Телефон</th><th>Заявки</th><th></th></tr><tr v-else-if="entity === 'masters'"><th>Мастер</th><th>Навыки</th><th>Специализация</th><th>Сегодня</th><th>Доступность</th></tr><tr v-else-if="entity === 'services'"><th>Услуга</th><th>Стоимость</th><th>Время</th><th>Уровень</th><th>Статус</th><th>Действия</th></tr><tr v-else><th>Запчасть</th><th>Артикул</th><th>Остаток</th><th>В резерве</th><th>Доступно</th><th>Минимум</th></tr></thead><tbody class="divide-y divide-line">
     <tr v-for="r in visible" :key="r.id" class="transition-colors hover:bg-surface2/50" :class="entity === 'warehouse' && r.is_active && r.available < r.min_stock ? 'bg-danger/5' : ''">
      <template v-if="entity === 'requests'"><td data-label="Заявка"><button class="text-left font-semibold text-brand hover:underline" @click="detail = r">{{ r.request_number }}</button><p class="mt-1 text-xs text-muted">{{ r.client.full_name }}</p></td><td data-label="Услуга" class="max-w-56"><div class="admin-item-cell"><span class="admin-device-art"><DeviceArt :name="deviceIcon(r.service)"/></span><span class="text-xs">{{r.service?.name}}</span></div></td><td data-label="Канал"><span class="flex items-center gap-1.5 whitespace-nowrap text-xs text-muted"><SvgIcon :name="r.service_mode === 'onsite' ? 'home' : 'store'" :size="15"/>{{ r.service_mode === 'onsite' ? 'Выезд' : 'В сервисе' }}</span></td><td data-label="Статус"><Badge :tone="statusTones[r.status]">{{ statusLabels[r.status] }}</Badge><p v-if="r.needs_manual_review" class="mt-1 text-[10px] font-semibold text-danger">Ручная проверка</p></td><td data-label="Мастер" class="text-xs text-muted">{{ r.master?.full_name ?? 'Не назначен' }}</td><td data-label="Создана" class="whitespace-nowrap text-xs text-muted">{{ shortDate(r.created_at) }}</td></template>
      <template v-else-if="entity === 'clients'"><td data-label="Клиент"><span class="flex items-center gap-3"><PersonAvatar :name="r.full_name" :src="r.avatar"/><strong class="whitespace-nowrap text-xs">{{ r.full_name }}</strong></span></td><td data-label="Email"><a :href="`mailto:${r.email}`" class="text-xs text-muted hover:text-brand">{{ r.email }}</a></td><td data-label="Телефон" class="whitespace-nowrap text-xs text-muted">{{ r.phone }}</td><td data-label="Заявки"><Badge tone="blue">{{ clientCount(r.id) }}</Badge></td><td data-label="Действия"><Button size="sm" variant="ghost" @click="detail = r">Карточка</Button><Button size="sm" variant="ghost" @click="editRecord(r)">Изменить</Button></td></template>
      <template v-else-if="entity === 'masters'"><td data-label="Мастер"><div class="flex items-center gap-3"><PersonAvatar :name="r.full_name" :src="r.avatar"/><div><button class="text-left text-xs font-semibold hover:text-brand" @click="detail = r">{{ r.full_name }}</button><p class="mt-1 text-[11px] text-muted">★ {{ r.rating.toFixed(1) }} · стаж {{ r.experience_years }} лет</p></div></div></td><td data-label="Навыки"><div class="flex max-w-64 flex-wrap gap-1"><span v-for="s in skills(r.id).slice(0, 2)" :key="s" class="rounded-md bg-surface2 px-2 py-1 text-[10px] text-muted">{{ s }}</span><span class="text-[10px] text-muted" v-if="skills(r.id).length > 2">+{{ skills(r.id).length - 2 }}</span></div></td><td data-label="Формат" class="text-xs text-muted">{{ workModeLabel(r) }}<p class="mt-1 text-[10px]">{{ r.is_onsite ? (JSON.parse(r.service_area).join(', ') || 'Районы не указаны') : 'Сервисный центр' }}</p></td><td data-label="Сегодня" class="min-w-32"><span class="text-xs">{{ masterLoad(r) }} / {{ r.max_daily_requests }}</span><div class="mt-2 h-1.5 rounded-full bg-surface2"><div class="h-full rounded-full bg-brand" :style="{ width: Math.min(100, masterLoad(r) / r.max_daily_requests * 100) + '%' }"></div></div></td><td data-label="Доступность"><Badge :tone="r.is_available ? 'green' : 'gray'">{{ r.is_available ? 'Доступен' : 'На паузе' }}</Badge><Button size="sm" variant="ghost" @click="editRecord(r)">Изменить</Button></td></template>
      <template v-else-if="entity === 'services'"><td data-label="Услуга" class="min-w-52"><div class="admin-item-cell"><span class="admin-device-art"><DeviceArt :name="equipmentArt(r.equipment_category)"/></span><div><button class="text-left font-semibold hover:text-brand" @click="edit(r)">{{r.name}}</button><p class="mt-1 text-xs text-muted">{{r.equipment_category}}</p></div></div></td><td data-label="Стоимость" class="whitespace-nowrap text-xs font-semibold">{{ money(r.base_price) }}</td><td data-label="Время" class="whitespace-nowrap text-xs text-muted">{{ r.average_duration_minutes }} мин</td><td data-label="Уровень" class="text-xs text-muted">{{ r.required_skill_level }}</td><td data-label="Статус"><Badge :tone="r.is_active ? 'green' : 'gray'">{{ r.is_active ? 'Активна' : 'Архив' }}</Badge></td><td data-label="Действия"><div class="flex gap-1"><Button size="sm" variant="ghost" :aria-label="`Изменить ${r.name}`" @click="edit(r)"><SvgIcon name="edit" :size="16"/></Button><Button size="sm" variant="ghost" :aria-label="`Удалить ${r.name}`" @click="deleting = r"><SvgIcon name="xCircle" :size="16" class="text-danger"/></Button></div></td></template>
      <template v-else><td data-label="Запчасть" class="min-w-52"><div class="admin-item-cell"><span class="admin-part-art"><PartArt :kind="r.kind"/></span><div><strong class="text-xs">{{r.name}}</strong><p class="text-xs text-muted">{{r.category}}</p><Button size="sm" variant="ghost" @click="editRecord(r)">Изменить</Button></div></div><p v-if="r.is_active && r.available < r.min_stock" class="mt-1 flex items-center gap-1 text-[10px] text-danger"><SvgIcon name="alertTriangle" :size="12"/>Доступно меньше минимума</p></td><td data-label="Артикул" class="whitespace-nowrap font-mono text-xs text-muted">{{ r.sku }}</td><td data-label="Остаток"><Badge :tone="r.is_active && r.available < r.min_stock ? 'red' : 'green'">{{ r.quantity }} шт.</Badge></td><td data-label="Резерв" class="text-xs text-muted">{{ r.reserved_quantity }}</td><td data-label="Доступно" class="text-xs font-bold" :class="r.available < r.min_stock ? 'text-warn' : 'text-content'">{{ r.available }}</td><td data-label="Минимум" class="text-xs text-muted">{{ r.min_stock }}</td></template>
     </tr></tbody></table></div><footer class="flex flex-wrap items-center justify-between gap-3 border-t border-line px-5 py-4"><span class="text-xs text-muted">{{ (page - 1) * 10 + 1 }}–{{ Math.min(page * 10, filtered.length) }} из {{ filtered.length }}</span><div class="flex items-center gap-3"><Button size="sm" variant="outline" :disabled="page === 1" aria-label="Предыдущая страница" @click="page--"><SvgIcon name="chevronRight" class="rotate-180" :size="15"/></Button><span class="text-xs text-muted">{{ page }} / {{ pages }}</span><Button size="sm" variant="outline" :disabled="page === pages" aria-label="Следующая страница" @click="page++"><SvgIcon name="chevronRight" :size="15"/></Button></div></footer></Card>
   </PageState>
  </PageState>
  <AdminRecordEditor v-model="recordOpen" :entity="entity" :record="recordEditing"/><AdminRequestModal :model-value="newRequestOpen||(entity==='requests'&&!!detail)" :request-id="entity==='requests'?detail?.id??null:null" @update:model-value="v=>{if(!v){newRequestOpen=false;detail=null}}"/>
  <Modal :model-value="!!detail&&entity!=='requests'" @update:model-value="value => { if (!value) detail = null }" :title="detail?.request_number ?? detail?.full_name ?? 'Карточка'" size="lg"><template v-if="detail"><div v-if="entity === 'requests'" class="grid gap-5"><div class="flex flex-wrap gap-2"><Badge :tone="statusTones[detail.status]">{{ statusLabels[detail.status] }}</Badge><Badge tone="blue">{{ detail.service_mode === 'onsite' ? 'Выезд мастера' : 'В сервисе' }}</Badge><Badge v-if="detail.needs_manual_review" tone="red">Требуется ручная проверка</Badge></div><p class="rounded-xl bg-surface2 p-4 text-sm leading-relaxed">{{ detail.description }}</p><dl class="detail-grid"><dt>Клиент</dt><dd>{{ detail.client.full_name }}<small class="mt-1 block text-muted">{{ detail.client.phone }}</small></dd><dt>Услуга</dt><dd>{{ detail.service?.name }}</dd><dt>Мастер</dt><dd>{{ detail.master?.full_name ?? 'Не назначен' }}</dd><dt>Желаемое время</dt><dd>{{ shortDate(detail.preferred_datetime) }} · {{ detail.preferred_slot }}</dd><dt>{{ detail.service_mode === 'onsite' ? 'Адрес' : 'Точка приёма' }}</dt><dd>{{ detail.client_address ?? 'TechGURU · Центральный сервис' }}</dd><dt>Стоимость</dt><dd>{{ money(detail.total_price) }}</dd></dl></div><dl v-else-if="entity === 'clients'" class="detail-grid"><dt>Клиент</dt><dd class="flex items-center gap-3"><PersonAvatar :name="detail.full_name" :src="detail.avatar"/><strong>{{detail.full_name}}</strong></dd><dt>Email</dt><dd>{{ detail.email }}</dd><dt>Телефон</dt><dd>{{ detail.phone }}</dd><dt>Обращений</dt><dd>{{ clientCount(detail.id) }}</dd></dl><div v-else><div class="flex items-center gap-3 mb-4"><PersonAvatar :name="detail.full_name" :src="detail.avatar" :size="54"/><div><strong>{{detail.full_name}}</strong><p class="text-sm text-muted">{{workModeLabel(detail)}}</p></div></div><Badge tone="green">Рейтинг {{ detail.rating.toFixed(1) }}</Badge><p class="my-4 text-sm text-muted">Загрузка сегодня: {{ masterLoad(detail) }} из {{ detail.max_daily_requests }}</p><h3 class="font-semibold">Навыки</h3><div class="mt-3 flex flex-wrap gap-2"><Badge v-for="s in skills(detail.id)" :key="s" tone="blue">{{ s }}</Badge></div></div></template></Modal>
  <Modal v-model="editOpen" :title="form.id ? 'Редактировать услугу' : 'Новая услуга'" description="Изменения сохраняются в базе данных."><form id="service-form" class="grid gap-4" @submit.prevent="save"><Input v-model="form.name" label="Название услуги" required maxlength="160"/><Select v-model="form.equipment_category" label="Категория техники" :options="categories"/><div class="grid gap-4 sm:grid-cols-2"><Input v-model="form.base_price" label="Базовая стоимость, ₽" type="number" min="0" step="1" required/><Input v-model="form.average_duration_minutes" label="Длительность, мин" type="number" min="1" step="1" required/><Input v-model="form.required_skill_level" label="Уровень навыка" type="number" min="1" step="1" required/><Select v-model="form.is_active" label="Статус" :options="[{ value: 1, label: 'Активна' }, { value: 0, label: 'Архив' }]"/></div><p v-if="formError" class="text-sm text-danger" role="alert">{{ formError }}</p></form><template #footer><Button variant="outline" @click="editOpen = false">Отмена</Button><Button variant="primary" type="submit" form="service-form">Сохранить</Button></template></Modal>
  <Modal :model-value="!!deleting" @update:model-value="v => { if (!v) deleting = null }" title="Удалить услугу?" size="sm"><p class="text-sm leading-relaxed">{{ deleting?.name }}</p><p class="mt-3 text-xs leading-relaxed text-muted">Услуга с существующими заявками будет перенесена в архив, чтобы сохранить историю обращений.</p><template #footer><Button variant="outline" @click="deleting = null">Отмена</Button><Button variant="danger" @click="remove">Подтвердить</Button></template></Modal>
 </div>
</template>
<style scoped>.directory-table{min-width:720px}.directory-table th{padding:15px 20px;font-weight:600;white-space:nowrap}.directory-table td{padding:17px 20px}.detail-grid{display:grid;grid-template-columns:140px minmax(0,1fr);gap:18px;font-size:13px}.detail-grid dt{color:var(--muted)}.detail-grid dd{overflow-wrap:anywhere}@media(max-width:480px){.detail-grid{grid-template-columns:1fr;gap:6px}.detail-grid dd{margin-bottom:12px}}</style>
